package erratum

import "errors"

func Use(opener ResourceOpener, input string) error {
	var res Resource
	var err error
	for {
		res, err = opener()
		var te TransientError
		if !errors.As(err, &te) {
			break
		}
	}

	defer func() {
		if r := recover(); r != nil {
			if fe, ok := r.(FrobError); ok {
				res.Defrob(fe.defrobTag)
			}
			if e, ok := r.(error); ok {
				err = e
			} else {
				err = errors.New("panic")
			}
		}
		_ = res.Close()
	}()

	res.Frob(input)
	return err
}
```

