package erratum

import (
	"errors"
)

// Use opens a resource via opener, calls Frob(input) on it and always closes
// it exactly once. Transient errors from the opener are retried; any panic
// from Frob is recovered, a FrobError triggers Defrob with its defrobTag,
// and the recovered error is returned.
func Use(opener ResourceOpener, input string) error {
	var res Resource
	var err error
	for {
		res, err = opener()
		var te TransientError
		if !errors.As(err, &te) {
			break
		}
	}

	defer func() {
		if r := recover(); r != nil {
			switch fe := r.(type) {
			case FrobError:
				res.Defrob(fe.defrobTag)
			case *FrobError:
				res.Defrob(fe.defrobTag)
			}
			if e, ok := r.(error); ok {
				err = e
			} else {
				_ = res.Close()
				panic(r)
			}
		}
		_ = res.Close()
	}()

	if err == nil {
		res.Frob(input)
	}
	return err
}

